# Define the set of required labels for any Helm release
required_labels := {
    "app.kubernetes.io/version": type(string),
    "owner": type(string)
}

# Helper function to check presence of a label in a map
has_label(map, key) := {
    key in map
}

# Main rule – evaluate for each release object
deny[msg] {
    # The input is expected to be a map representing a Helm release (e.g., from `helm get manifest`)
    release := input
    # Verify that all required labels exist and have the correct type
    ok := true
    for label, typ in required_labels {
        if !has_label(release, label) {
            ok = false
        }
        if !typ(release[label]) {
            ok = false
        }
    }
    if ok {
        # If we reach here, all required labels are present – no violation.
        deny[msg]
    } else {
        msg := fmt("Helm release %s is missing required labels: %v", input["name"], required_labels)
        deny[msg]
    }
}
```
### Explanation of the Policy
- **`required_labels`** enumerates the two mandatory keys.
- **`has_label`** is a small helper that returns true only when the key exists in the supplied map.
- The main rule iterates over each key; if any key is absent or has an incorrect type, it sets `ok = false`.
- When `ok` remains true, the rule does nothing (no violation). Otherwise it emits an error message containing the chart name and which labels are missing.
